import fs from 'fs';
import * as esbuild from 'esbuild';
import { THANKS, THANKS_CSS } from './credit.mjs';
import { BOARD_CSS, BOARD_3D_CSS, BOARD_JS } from './board.mjs';

/* 1. Inline the ground maps. Textures loaded over file:// are blocked by CORS,
      so the only way this opens by double-click is as data URIs. */
const uri = f => 'data:image/webp;base64,' +
  fs.readFileSync(`../assets/textures/${f}`).toString('base64');
fs.writeFileSync('../src/textures.gen.js',
  '/* generated by tools/build-3d.mjs - do not edit */\nexport const GROUND = ' +
  JSON.stringify({
    color: uri('ground-stone_color_512.webp'),
    normal: uri('ground-stone_normalgl_512.webp'),
    rough: uri('ground-stone_roughness_512.webp'),
  }, null, 0) + ';\n');

/* Audio inlined as data URIs - same file:// CORS rule as the textures.
   To use externally sourced files instead, point these three at them. */
const AUDIO = {
  drone: 'ambient-drone.mp3',
  gate: 'gate-close.mp3',
  bell: 'bell-oldage.mp3',
};
const au = f => 'data:audio/mpeg;base64,' + fs.readFileSync('../assets/audio/' + f).toString('base64');
fs.writeFileSync('../src/audio.gen.js',
  '/* generated by tools/build-3d.mjs - do not edit */\nexport const AUDIO = ' +
  JSON.stringify({ drone: au(AUDIO.drone), gate: au(AUDIO.gate), bell: au(AUDIO.bell) }, null, 0) + ';\n');

/* Voiced lines, from tools/make-voice.mjs. Only lines still in the text are
   inlined, so an edited or deleted line drops out by itself. If the voices
   have never been generated this is empty and the game simply reads silently. */
{
  const { T } = await import('../src/text.gen.js?' + Date.now());
  const hashLine = s => { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193); } return (h >>> 0).toString(16).padStart(8, '0'); };
  const lines = [], walk = v => typeof v === 'string' ? lines.push(v) : Array.isArray(v) ? v.forEach(walk) : v && typeof v === 'object' ? (v.line ? lines.push(v.line) : Object.values(v).forEach(walk)) : 0;
  walk(T);
  const V = {}; let missing = 0;
  for (const l of lines) {
    const h = hashLine(l), f = '../assets/voice/' + h + '.mp3';
    if (fs.existsSync(f)) V[h] = 'data:audio/mpeg;base64,' + fs.readFileSync(f).toString('base64'); else missing++;
  }
  fs.writeFileSync('../src/voice.gen.js', '/* generated by tools/build-3d.mjs from assets/voice - do not edit */\n' +
    'export const VOICE = ' + JSON.stringify(V) + ';\n');
  console.log('voice: ' + Object.keys(V).length + ' lines inlined' + (missing ? ', ' + missing + ' unvoiced (run make-voice.mjs)' : ''));
}

/* Character sculpts, reduced by tools/prep-models.mjs. Baked to raw arrays
   (positions, normals, indices) rather than shipped as GLB, so the game can
   build and rig them synchronously at start-up. Absent files -> the game uses
   its hand-built figures instead. */
{
  const { NodeIO } = await import('@gltf-transform/core');
  const io = new NodeIO(), M = {};
  for (const name of ['doorkeeper', 'man']) {
    const f = '../assets/models/game/' + name + '.glb';
    if (!fs.existsSync(f)) continue;
    const prim = (await io.read(f)).getRoot().listMeshes()[0].listPrimitives()[0];
    const b64 = arr => Buffer.from(arr.buffer, arr.byteOffset, arr.byteLength).toString('base64');
    const idx = prim.getIndices().getArray();
    const wide = idx.reduce((m, v) => v > m ? v : m, 0) > 65535;
    M[name] = {
      pos: b64(new Float32Array(prim.getAttribute('POSITION').getArray())),
      /* 16-bit indices when every vertex number fits, and the flag says which */
      idx: b64(wide ? new Uint32Array(idx) : new Uint16Array(idx)),
      wide,
    };
  }
  fs.writeFileSync('../src/models.gen.js', '/* generated by tools/build-3d.mjs from assets/models/game - do not edit */\n' +
    'export const MODELS = ' + JSON.stringify(M) + ';\n');
  console.log('models: ' + (Object.keys(M).join(', ') || 'none (hand-built figures)'));
}

/* MIT requires the notice be retained in redistributed builds */
const BANNER = '/*! Bundled: three.js (c) 2010-2025 three.js authors, MIT License; ' +
  'howler.js (c) 2013-2024 James Simpson / GoldFire Studios, MIT License. ' +
  'Scene code, audio and assets: CC0 / original. See assets/LICENSES.md */';

/* 2. Bundle into one IIFE. ES module imports are also blocked over file://,
      so nothing may remain as a separate request. */
async function bundle(entry) {
  const out = await esbuild.build({
    entryPoints: [entry],
    bundle: true, minify: true, format: 'iife', target: 'es2020',
    write: false, legalComments: 'eof',
    /* the entry lives in ../src but three is installed here */
    nodePaths: ['node_modules'],
  });
  return out.outputFiles[0].text;
}

